 useEffect(()=>{if(!showStart&&!showGod&&!showReset&&!selectedSku&&!selectedSupplier)return;const dialog=document.querySelector<HTMLElement>('[role="dialog"]');if(!dialog)return;const previous=document.activeElement as HTMLElement|null;const selector='button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),[tabindex="0"]';const focusable=()=>Array.from(dialog.querySelectorAll<HTMLElement>(selector)).filter(element=>element.getClientRects().length>0);if(!dialog.contains(document.activeElement))focusable()[0]?.focus();const trap=(event:KeyboardEvent)=>{if(event.key!=='Tab')return;const nodes=focusable(),first=nodes[0],last=nodes.at(-1);if(!first)return;if(event.shiftKey&&(!dialog.contains(document.activeElement)||document.activeElement===first)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(!dialog.contains(document.activeElement)||document.activeElement===last)){event.preventDefault();first.focus();}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);if(previous&&document.contains(previous))previous.focus();};},[showStart,showGod,showReset,selectedSku,selectedSupplier]);
 useEffect(()=>{const onKey=(event:KeyboardEvent)=>{if(event.key==='Escape'){setSelectedSku(null);setSelectedSupplier(null);setShowStart(false);setShowGod(false);if(!resetInFlight.current)setShowReset(false);}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[]);
 useEffect(()=>{if(!run?.id)return;const epoch=viewEpoch.current;let stale=false;const source=new EventSource(`/api/runs/${run.id}/events`,{withCredentials:true});streamRef.current=source;source.onopen=()=>{if(!stale&&epoch===viewEpoch.current)setConnected(true)};source.onerror=()=>{if(!stale&&epoch===viewEpoch.current)setConnected(false)};const handle=(event:MessageEvent)=>{if(stale||epoch!==viewEpoch.current)return;try{acceptSnapshot(JSON.parse(event.data));}catch{setError('A run update could not be read. Refresh to recover the latest saved state.');}};const reset=()=>{if(stale||epoch!==viewEpoch.current)return;stale=true;source.close();clearWorkspace();const afterReset=viewEpoch.current;void api.bootstrap().then(data=>{if(afterReset===viewEpoch.current)setBoot(data)}).catch(()=>{});};source.addEventListener('snapshot',handle);source.addEventListener('reset',reset);const timer=setInterval(()=>{api.snapshot(run.id).then(data=>{if(!stale&&epoch===viewEpoch.current)acceptSnapshot(data)}).catch(()=>{});},5000);return()=>{stale=true;source.close();clearInterval(timer);setConnected(false);};},[run?.id,streamVersion]);
 useEffect(()=>{if(!godMode||!run?.id){setGod(null);return;}let stale=false;api.god(run.id).then(data=>{if(!stale)setGod(data)}).catch(e=>{if(!stale){setError(e.message);setGodMode(false);}});return()=>{stale=true};},[godMode,run?.id,run?.eventSeq]);
 const store=run?.store||boot?.store;const catalog=boot?.catalog||[];const suppliers=run?.suppliers||boot?.suppliers||[];const capabilities=boot?.capabilities||run?.capabilities;const isRunning=!!run&&!terminal.has(run.status);const resolved=run?.progress.resolved||0;const quotes=run?.quotes||[];const decisions=run?.decisions||[];const events=run?.events||[];const totalBudget=run?.budget.totalCents||boot?.defaults.budgetCents||0;const committed=run?.budget.committedCents||0;const reserved=run?.budget.reservedCents||0;const remaining=run?.budget.unallocatedCents??totalBudget;const accepted=decisions.filter(x=>x.outcome==='accepted').length;const escalated=decisions.filter(x=>x.escalated).length;const unavailable=decisions.filter(x=>x.outcome==='unavailable').length;
 const filtered=catalog.filter(item=>(filter==='all'||item.category===filter||run?.items.find(x=>x.skuId===item.id)?.status===filter)&&(item.name.toLowerCase().includes(query.toLowerCase())));
 const selected=catalog.find(x=>x.id===selectedSku);const selectedPlan=run?.items.find(x=>x.skuId===selectedSku);const selectedDecision=decisions.find(x=>x.skuId===selectedSku);const selectedQuotes=quotes.filter(x=>x.skuId===selectedSku).sort((a,b)=>a.landedCostCents-b.landedCostCents);const privateSupplier=suppliers.find(x=>x.id===selectedSupplier);
 const sender=(role:string)=>suppliers.find(x=>x.id===role)?.name||roleName(role);
 async function start(){const epoch=viewEpoch.current;setBusy(true);setError('');try{const cents=Math.round(Number(budget)*100),loss=Math.round(Number(allowance)*100);if(!Number.isFinite(cents)||cents<10000||cents>10000000||!Number.isFinite(loss)||loss<0||loss>1000000)throw new Error('Use a purchasing budget from $100 to $100,000 and a promotional allowance from $0 to $10,000.');const data=await request<RunSnapshot>('/api/runs',{method:'POST',body:JSON.stringify({mode,budgetCents:cents,promotionAllowanceCents:loss,useTrends:useTrends&&!!boot?.trends?.eligibleSkuIds?.length})});if(epoch!==viewEpoch.current)return;acceptSnapshot(data,true);setResetNotice('');setShowStart(false);setPage('overview');setGod(null);}catch(e){if(epoch===viewEpoch.current)setError((e as Error).message);}finally{if(epoch===viewEpoch.current)setBusy(false);}}
 async function toggleGod(enabled:boolean){const epoch=viewEpoch.current;if(enabled){setShowGod(true);return;}setBusy(true);try{await request('/api/session/god',{method:'DELETE'});if(epoch!==viewEpoch.current)return;setGodMode(false);setGod(null);setSelectedSupplier(null);}catch(e){if(epoch===viewEpoch.current)setError((e as Error).message);}finally{if(epoch===viewEpoch.current)setBusy(false);}}
